// Read the private storage result as UTF-8 Markdown text.
const selectedNote = context.workflow['__SELECT_NOTE__'].result.data[0];
const storageResult = context.workflow['__GET_MARKDOWN__'].result;
let markdown;

// Storage normally returns a Blob. The current runtime returns a data URL,
// so handle both documented and observed representations.
if (storageResult?.file && typeof storageResult.file.text === 'function') {
  markdown = await storageResult.file.text();
} else if (typeof storageResult === 'string' && storageResult.startsWith('data:')) {
  const encodedContent = storageResult.split(',', 2)[1];
  markdown = Buffer.from(encodedContent, 'base64').toString('utf8');
} else {
  throw new Error('markdown_storage_result_unavailable');
}

return {
  note: {
    id: selectedNote.id,
    title: selectedNote.title,
    excerpt: selectedNote.excerpt,
    source_status: selectedNote.source_status,
    markdown_file_path: selectedNote.markdown_file_path,
    createdAt: selectedNote.createdAt,
    updatedAt: selectedNote.updatedAt,
  },
  markdown,
  storage: {
    configured: true,
    state: 'storage_ready',
    path: selectedNote.markdown_file_path,
    message: 'Le Markdown a été lu depuis le stockage privé.',
  },
};

