} else if (typeof storageResult === 'string' && storageResult.startsWith('data:')) {
  markdown = Buffer.from(storageResult.split(',', 2)[1], 'base64').toString('utf8');
} else {
  throw new Error('markdown_storage_result_unavailable');
}

const expectedMarkdown = '# Bienvenue dans SamNotes\n\nCette note est lue depuis un fichier Markdown privé dans le stockage WeWeb.\n\n- Métadonnées dans PostgreSQL\n- Contenu dans le stockage\n- Lecture via un endpoint authentifié\n\nProchaine étape : exporter et tester le même parcours en Docker local avec un stockage S3 compatible.\n';

return {
